BEGIN READ ONLY;
SELECT 'RLS' AS section,jsonb_build_object('tables',count(*),'without_rls',coalesce(jsonb_agg(tablename) FILTER(WHERE NOT rowsecurity),'[]'::jsonb)) AS result FROM pg_tables WHERE schemaname='public'
UNION ALL SELECT 'trigger_functions',coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'return_type',p.prorettype::regtype::text,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('handle_new_user','rls_auto_enable')
UNION ALL SELECT 'security_definer_inventory',coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'settings',p.proconfig) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef
UNION ALL SELECT 'data_readiness',jsonb_build_object('listings',count(*),'without_owner',count(*) FILTER(WHERE owner_id IS NULL),'non_demo_without_owner',count(*) FILTER(WHERE NOT is_demo AND owner_id IS NULL),'test_published',count(*) FILTER(WHERE title LIKE 'TEST %' AND NOT is_demo AND status='published' AND availability='available')) FROM public.properties
UNION ALL SELECT 'accounts',jsonb_build_object('renters',count(*) FILTER(WHERE role='tenant' AND account_status='active'),'landlords',count(*) FILTER(WHERE role='landlord' AND account_status='active'),'admins',count(*) FILTER(WHERE role='admin' AND account_status='active'),'inactive',count(*) FILTER(WHERE account_status<>'active')) FROM public.profiles
UNION ALL SELECT 'email_status_not_delivery',jsonb_build_object('total',count(*),'confirmed',count(*) FILTER(WHERE email_confirmed_at IS NOT NULL)) FROM auth.users
UNION ALL SELECT 'moderation_nullable_check',jsonb_build_object('nullable',(SELECT is_nullable FROM information_schema.columns WHERE table_schema='public' AND table_name='moderation_auto' AND column_name='auto_reviewed_at'),'constraint_present',EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.moderation_auto'::regclass AND conname='moderation_review_timestamp_check')))
UNION ALL SELECT 'cron',coalesce(jsonb_agg(jsonb_build_object('jobname',j.jobname,'active',j.active,'schedule',j.schedule,'last_status',d.status,'last_start',d.start_time)),'[]'::jsonb) FROM cron.job j LEFT JOIN LATERAL (SELECT status,start_time FROM cron.job_run_details WHERE jobid=j.jobid ORDER BY start_time DESC LIMIT 1) d ON true WHERE j.jobname='danest-maintenance-09c1';
ROLLBACK;
